export const entidadesLocalizacaoMap = new Map<string, EntidadeLocalizacao>(
  ENTIDADES_LOCALIZACAO.map(e => [e.cnpj, e])
);

const normalizarCNPJ = (cnpj: string): string =>
  cnpj.replace(/\D/g, '').padStart(14, '0');

export function getLocalizacaoByCNPJ(cnpj: string): EntidadeLocalizacao | undefined {
  return entidadesLocalizacaoMap.get(normalizarCNPJ(cnpj));
}
